// Class 12 English Core practice bank, part 1: writing skills (notice, invitation and reply, letter to the editor, job application, article, report).
StudyData.addPractice(12, "english", {
  "notice-writing": {
    mcq: [
      { q: "Where does the name of the issuing institution appear in a notice?", options: ["At the top, above the word NOTICE", "After the body", "Only in the closing line", "It is not written"], answer: 0, explain: "A notice begins with the **name of the institution**, followed by the word NOTICE and the date.", level: 1 },
      { q: "The heading of a notice is usually written in:", options: ["small letters in the middle of the body", "capital letters", "italics with a full stop", "the last line"], answer: 1, explain: "The heading is a short title in **capitals**, e.g. BLOOD DONATION CAMP.", level: 1 },
      { q: "The designation at the end of a notice is:", options: ["the writer's home address", "the writer's phone number", "the writer's qualification", "the writer's post, such as Sports Captain"], answer: 3, explain: "A notice ends with the writer's **name and designation**.", level: 1 },
      { q: "Which is the correct way to end a notice?", options: ["Yours faithfully, Rohan", "Thank you, Rohan", "Rohan, Cultural Secretary", "With love, Rohan"], answer: 2, explain: "A notice has no complimentary close. It ends with the **name and designation**.", level: 1 },
      { q: "Which opening sentence suits a notice about a postponed debate?", options: ["All students are informed that the inter-house debate has been postponed to 14 October.", "I am very sad to say that we have decided to postpone the debate.", "Dear students, the debate is postponed, so please relax.", "Hey! Debate cancelled, so come later."], answer: 0, explain: "A notice is **formal and impersonal**, and the passive voice is common.", level: 2 },
      { q: "In a lost-and-found notice, which detail is unnecessary?", options: ["Colour and size of the lost bag", "Place where it was lost", "The writer's opinion on students' carelessness", "The person to contact"], answer: 2, explain: "A notice states facts only. Personal opinions have no place in it.", level: 2 },
      { q: "Which sentence is best for a notice about joining the quiz club?", options: ["Give names, quiz club, Mr Rao, 5 Oct.", "You must give me your name or I will be angry.", "Do give your name to me if you want to join!!", "Students who wish to join the quiz club should give their names to Mr Rao by 5 October."], answer: 3, explain: "The best version is complete, polite and formal. Note form and exclamation marks lose marks.", level: 2 },
      { q: "A student's notice runs to about 85 words against a limit of 50. What is the likely result?", options: ["Full marks, since all details are included", "Marks may be deducted, because the notice is not concise", "Extra marks for extra information", "No effect, because only the format is checked"], answer: 1, explain: "Marks are given for format, content and expression. A notice must be **brief**, so crossing the limit costs marks.", level: 2 },
      { q: "Ananya, Eco Club Secretary, writes: ‘Dear Students, our club will plant saplings on Sunday. Come in large numbers. Thank you. Ananya.’ Which corrections are needed?", options: ["Add her postal address and ‘Yours faithfully’", "Add a long paragraph on the benefits of trees", "Remove the salutation and closing; add date, heading, venue, time and designation", "Only change ‘Dear Students’ to ‘Dear All’"], answer: 2, explain: "The piece reads like a letter. A notice needs institution, NOTICE, date, heading, all the details and a **name with designation**.", level: 3 },
      { q: "A notice reads: ‘Lost: A black wallet near the canteen. Please return. Dev.’ Which format elements are missing?", options: ["Salutation and complimentary close", "Sender's postal address and subject line", "Reward amount and the writer's phone number", "Institution, NOTICE, date, heading and designation"], answer: 3, explain: "The format of a notice is Institution, NOTICE, Date, Heading, Body, Name and Designation. Addresses and salutations do not belong in a notice.", level: 3 }
    ],
    written: [
      { q: "You are Maya Deshmukh, Head Girl of Sunrise Public School, Nashik. You lost a silver ladies' wristwatch near the school library on 12 October. Write a notice for the school notice board. (50 words)", a: "[Inside a box]\nSUNRISE PUBLIC SCHOOL, NASHIK\nNOTICE\n13 October 20XX\nLOST: SILVER WRISTWATCH\nA silver ladies' wristwatch with a blue strap was lost near the school library on 12 October during the lunch break. The finder is requested to hand it over to the school office or contact the undersigned.\nMaya Deshmukh\nHead Girl", marks: 4 },
      { q: "You are Kabir Rawat, NSS Secretary of Gyan Bharti Senior Secondary School, Indore. Write a notice informing students and staff about a blood donation camp to be held on 20 November, from 9 a.m. to 1 p.m. in the school hall. (50 words)", a: "[Inside a box]\nGYAN BHARTI SENIOR SECONDARY SCHOOL, INDORE\nNOTICE\n10 November 20XX\nBLOOD DONATION CAMP\nA blood donation camp will be organised by the NSS unit on 20 November from 9 a.m. to 1 p.m. in the school hall. Students above eighteen years and staff members may donate. Interested donors should register with the undersigned by 15 November.\nKabir Rawat\nNSS Secretary", marks: 4 },
      { q: "You are Harpreet Kaur, Sports Secretary of Model Public School, Ludhiana. The Annual Sports Day fixed for 5 December has been postponed to 12 December because rain is forecast. Write a notice. (50 words)", a: "[Inside a box]\nMODEL PUBLIC SCHOOL, LUDHIANA\nNOTICE\n1 December 20XX\nANNUAL SPORTS DAY POSTPONED\nAll students are informed that the Annual Sports Day, scheduled for 5 December, has been postponed to 12 December owing to the forecast of rain. The timing and venue will remain unchanged. Participants should continue their practice as planned.\nHarpreet Kaur\nSports Secretary", marks: 4 },
      { q: "You are the Secretary of Lakshmi Nagar Residents' Welfare Association, Coimbatore. Write a notice informing residents that water supply will be stopped on 8 November from 8 a.m. to 6 p.m. for pipeline repair. (50 words)", a: "[Inside a box]\nLAKSHMI NAGAR RESIDENTS' WELFARE ASSOCIATION, COIMBATORE\nNOTICE\n5 November 20XX\nINTERRUPTION IN WATER SUPPLY\nResidents are informed that water supply will remain suspended on 8 November from 8 a.m. to 6 p.m. because of pipeline repair work. They are requested to store enough water in advance. The inconvenience is regretted.\nS. Venkatesh\nSecretary", marks: 4 },
      { q: "You are Aman Jha, Literary Secretary of Sarvodaya Vidyalaya, Patna. Write a notice inviting students of Classes XI and XII to take part in an inter-school quiz on 2 November. Names are to be given to Mr R. K. Jha by 25 October. (50 words)", a: "[Inside a box]\nSARVODAYA VIDYALAYA, PATNA\nNOTICE\n18 October 20XX\nINTER-SCHOOL QUIZ\nStudents of Classes XI and XII who wish to represent the school in the inter-school quiz to be held on 2 November are informed that they should give their names to Mr R. K. Jha by 25 October. Selection will be on merit.\nAman Jha\nLiterary Secretary", marks: 4 },
      { q: "You are Sanjana Bhat, Head Girl of Vidya Bharti School, Bengaluru. Write a notice informing Class XII students about an educational excursion to Mysuru on 15 January. The cost is ₹1,800 per student and consent letters are to be submitted by 30 December. (50 words)", a: "[Inside a box]\nVIDYA BHARTI SCHOOL, BENGALURU\nNOTICE\n20 December 20XX\nEDUCATIONAL EXCURSION TO MYSURU\nAn educational excursion to Mysuru has been arranged for Class XII students on 15 January. The cost is ₹1,800 per student. Interested students should submit the fee and a signed parental consent letter to their class teacher by 30 December.\nSanjana Bhat\nHead Girl", marks: 4 }
    ]
  },
  "invitation-and-reply": {
    mcq: [
      { q: "A formal invitation is written in which person?", options: ["Third person", "First person", "Second person", "A mixture of all three"], answer: 0, explain: "A formal invitation uses the **third person**, e.g. ‘The Principal requests the pleasure of your company…’.", level: 1 },
      { q: "RSVP at the end of an invitation means:", options: ["Return, send, view and print", "Reserved seats for very special people", "Répondez, s’il vous plaît: please reply", "Respond soon, very politely, without fail"], answer: 2, explain: "RSVP comes from French and asks the guest to **reply**.", level: 1 },
      { q: "Which is the correct opening of a formal invitation?", options: ["Dear Sir, I invite you to our function.", "Come to our Annual Day without fail.", "We are going to hold a big function.", "The Principal and staff of Sarvodaya Public School request the pleasure of your company at the Annual Day."], answer: 3, explain: "A formal invitation opens with the host's name and a courteous request line.", level: 1 },
      { q: "Which of these is NOT needed in a formal reply to an invitation?", options: ["Thanks to the host", "‘Dear Sir’ and ‘Yours sincerely’", "Confirmation of attendance with date and venue", "The name of the invitee"], answer: 1, explain: "A formal reply is short, boxed and in the third person. It has no salutation or complimentary close.", level: 1 },
      { q: "Which sentence is the best way to decline an invitation?", options: ["Mrs Rao will not come as she is busy.", "Mrs Rao does not like such functions.", "Mrs Rao is upset about the late invitation.", "Mrs Rao thanks the host but regrets that a prior commitment out of station prevents her from attending."], answer: 3, explain: "Declining needs thanks, **regret** and a brief, polite **reason**.", level: 2 },
      { q: "‘Mr and Mrs Nair request the pleasure of your company at the wedding of their daughter Anjali on 14 February at 7 p.m.’ Which essential detail is missing?", options: ["The day of the week", "The venue", "The bride's age", "A salutation"], answer: 1, explain: "An invitation must give the occasion, date, time and **venue**.", level: 2 },
      { q: "In a reply to a formal invitation, whose name opens the reply?", options: ["The host's name", "The chief guest's name", "The invitee's name", "The name of the writer's friend"], answer: 2, explain: "The reply is written from the **invitee's side**, so it begins with the invitee's name, e.g. ‘Mr Anil Kapoor thanks…’.", level: 2 },
      { q: "Which reason would be inappropriate when declining an invitation?", options: ["A prior engagement", "Illness in the family", "Travel outside the city", "‘I find such functions boring.’"], answer: 3, explain: "The reason must be polite and tactful. Blunt or rude reasons are unacceptable.", level: 2 },
      { q: "Aditya replies to an invitation: ‘Dear Sir, I will come. Yours sincerely, Aditya.’ Which revision is best?", options: ["Aditya thanks the host, confirms attendance on 8 December at the stated time and venue, boxed and in the third person", "Add Aditya's address and a subject line", "Replace ‘Yours sincerely’ with ‘Yours faithfully’", "Write three paragraphs on why he is glad"], answer: 0, explain: "A formal reply is a **boxed third-person** note that thanks the host and repeats the occasion, date, time and venue.", level: 3 },
      { q: "A student's invitation runs to 78 words because it includes the host, occasion, date, time, venue, chief guest, dress code and an outline of the welcome speech. What should the student do?", options: ["Keep everything, since all details are useful", "Remove the date to save space", "Cut the speech outline and other extras to come near 50 words, keeping the essentials", "Convert it into a letter"], answer: 2, explain: "The limit is about 50 words. Keep occasion, date, time, venue, chief guest and RSVP, and drop what is not needed.", level: 3 }
    ],
    written: [
      { q: "You are Dr Meera Pillai, Principal of St. Thomas Higher Secondary School, Kochi. Draft an invitation to parents for the school's Annual Day on 18 December at 5 p.m. in the school auditorium. The chief guest is Mr Joseph Mathew, a retired District Collector. (50 words)", a: "[Inside a box]\nThe Principal, staff and students of St. Thomas Higher Secondary School, Kochi, request the pleasure of your company at the Annual Day on Wednesday, 18 December 20XX at 5 p.m. in the school auditorium. Mr Joseph Mathew, retired District Collector, will be the Chief Guest. Tea will be served at 7 p.m.\nRSVP\nDr Meera Pillai, Principal", marks: 4 },
      { q: "You are Mr Anil Kapoor. Reply accepting the invitation to the Science Exhibition at Delhi Heritage School on Saturday, 14 December at 10 a.m. in the school hall. (50 words)", a: "[Inside a box]\n8 December 20XX\nMr Anil Kapoor thanks the Principal and staff of Delhi Heritage School for the kind invitation to the Annual Science Exhibition. He is pleased to accept and will attend the exhibition on Saturday, 14 December 20XX at 10 a.m. in the school hall. He looks forward to seeing the students' models.", marks: 4 },
      { q: "You are Mrs Suman Rao. Reply declining the invitation of the Principal of Rotary Public School, Mysuru, to the prize distribution on 22 January at 4 p.m. You will be out of the city that day for a family wedding. (50 words)", a: "[Inside a box]\n12 January 20XX\nMrs Suman Rao thanks the Principal and staff of Rotary Public School, Mysuru, for the kind invitation to the prize distribution on 22 January 20XX at 4 p.m. She deeply regrets that she will be unable to attend because of a family wedding out of the city. She wishes the function every success.", marks: 4 },
      { q: "You are Rajan Iyer, Secretary of Vidyalaya Cultural Society, Madurai. Draft an invitation to the town's citizens for a classical dance evening on 3 March at 6.30 p.m. at the Town Hall. The guest of honour is Smt. Kalyani Sundaram. Entry is free. (50 words)", a: "[Inside a box]\nThe Vidyalaya Cultural Society, Madurai, requests the pleasure of your company at an evening of classical dance on Sunday, 3 March 20XX at 6.30 p.m. at the Town Hall. Smt. Kalyani Sundaram will be the Guest of Honour. Entry is free.\nRSVP\nRajan Iyer, Secretary", marks: 4 },
      { q: "You are Mr and Mrs Gill, parents of Simran. Invite relatives to Simran's wedding with Harjot Singh on 25 February at 11 a.m. at Gurdwara Sahib Hall, Amritsar. A lunch will follow. (50 words)", a: "[Inside a box]\nMr and Mrs Gurmeet Gill request the pleasure of your company at the wedding of their daughter Simran with Harjot Singh, son of Mr and Mrs Balwinder Singh, on Sunday, 25 February 20XX at 11 a.m. at Gurdwara Sahib Hall, Amritsar. Lunch will follow the ceremony.\nRSVP\nMr and Mrs Gurmeet Gill", marks: 4 },
      { q: "You are Kavita Sharma. Reply accepting the invitation of Mr and Mrs Gurmeet Gill to the wedding of their daughter Simran on 25 February at 11 a.m. at Gurdwara Sahib Hall, Amritsar. (50 words)", a: "[Inside a box]\n10 February 20XX\nMs Kavita Sharma thanks Mr and Mrs Gurmeet Gill for the kind invitation to the wedding of their daughter Simran on 25 February 20XX at 11 a.m. at Gurdwara Sahib Hall, Amritsar. She is delighted to accept and will attend the ceremony. She sends her best wishes to the couple.", marks: 4 }
    ]
  },
  "letter-to-the-editor": {
    mcq: [
      { q: "Which complimentary close suits a letter to the Editor?", options: ["Yours lovingly", "Yours faithfully", "Your friend", "Regards and thanks"], answer: 1, explain: "A formal letter to an unnamed person closes with **Yours faithfully**.", level: 1 },
      { q: "Where does the sender's address go in a letter to the editor?", options: ["At the top, before the date", "At the bottom, below the name", "After the salutation", "It is not written"], answer: 0, explain: "The format begins with the **sender's address**, then the date, then the receiver.", level: 1 },
      { q: "The salutation in a letter to the Editor is:", options: ["Dear Editor", "Dear Friend", "Sir/Madam", "Hello"], answer: 2, explain: "A formal letter uses **Sir** or **Madam**.", level: 1 },
      { q: "The subject line of a letter to the editor should be:", options: ["a long paragraph", "a short, specific phrase stating the issue", "the writer's opinion in full", "left out"], answer: 1, explain: "The subject line is a brief phrase such as ‘Subject: Rising noise pollution near schools’.", level: 1 },
      { q: "Which is the best subject line for a letter about loudspeaker noise near a hospital?", options: ["Subject: Complaint!!!", "Subject: A letter for you", "Subject: Noise", "Subject: Loudspeaker noise near the district hospital"], answer: 3, explain: "A good subject line is specific. ‘Noise’ alone is too vague.", level: 2 },
      { q: "Which sentence best suits the final paragraph of a letter to the editor?", options: ["I request the municipal authorities to act soon, and I thank you for giving space to this letter.", "The authorities are lazy and useless.", "I have already told you everything above.", "Write back to me immediately."], answer: 0, explain: "The last paragraph gives a **solution or appeal** and thanks the editor.", level: 2 },
      { q: "Which sentence has the right tone for a letter to the editor?", options: ["The engineer is a lazy fool who does nothing.", "Residents face great inconvenience, and the civic authorities are requested to take prompt action.", "Everybody hates the authorities for this mess.", "Fix the roads right now or face trouble."], answer: 1, explain: "The tone is polite and serious. The writer criticises the **problem**, not individuals.", level: 2 },
      { q: "A student writes only 90 words for a 120–150 word letter. What is the main risk?", options: ["None, since shorter is always better", "Loss of marks because content and development fall short", "The letter becomes a notice", "The format will be marked wrong automatically"], answer: 1, explain: "A letter well below the limit usually leaves out causes, effects or solutions, which costs content marks.", level: 2 },
      { q: "Read: ‘Dear Editor, the roads are flooded because Mr Verma, the engineer, is a lazy fool. Yours sincerely, Pooja.’ Which set lists the errors?", options: ["Only the personal attack", "Only the missing date", "Wrong salutation and close; missing address, date, receiver and subject; abusive attack on a named person", "Only the wrong complimentary close"], answer: 2, explain: "The letter breaks format (salutation, close, address, date, receiver, subject) and tone (name-calling).", level: 3 },
      { q: "A student's letter has 210 words in five paragraphs that keep repeating the same complaint. What is the best action?", options: ["Add one more paragraph", "Condense to about 120–150 words in three paragraphs, removing repetition", "Convert it into an article", "Leave it, since more detail earns more marks"], answer: 1, explain: "Marks depend on staying within the limit. Three focused paragraphs (issue, effects, solutions) work best.", level: 3 }
    ],
    written: [
      { q: "You are Ritu Saxena, 14, Rajiv Nagar, Lucknow. Write a letter to the Editor of The Daily Courier, Lucknow, about the increasing noise from loudspeakers near the city hospital and suggest remedies. (120–150 words)", a: "14, Rajiv Nagar\nLucknow\n12 March 20XX\n\nThe Editor\nThe Daily Courier\nLucknow\n\nSubject: Loudspeaker noise near the city hospital\n\nSir\n\nThrough the columns of your esteemed newspaper, I wish to draw the attention of the authorities to the growing noise from loudspeakers near the city hospital. Processions, shop announcements and religious gatherings use them at full volume from morning till late night.\n\nThe noise disturbs patients who need rest and makes it difficult for doctors to carry out their work. Elderly people and students preparing for examinations also suffer. Several residents have complained, but little has been done. Last week, an ambulance was delayed because of a noisy procession.\n\nI therefore request the district administration to declare a strict silence zone around the hospital and to punish those who break the rules. Police patrolling should be increased, and citizens should cooperate voluntarily.\n\nI thank you for giving space to this letter.\n\nYours faithfully\nRitu Saxena", marks: 5 },
      { q: "You are Dev Malhotra, 9, Green Avenue, Chandigarh. Write a letter to the Editor of The Tribune City Times, Chandigarh, expressing concern over the rising number of road accidents caused by careless driving of teenagers, and suggest ways to prevent them. (120–150 words)", a: "9, Green Avenue\nChandigarh\n5 April 20XX\n\nThe Editor\nThe Tribune City Times\nChandigarh\n\nSubject: Rising road accidents caused by careless driving\n\nSir\n\nI wish to express my deep concern, through your newspaper, over the increasing number of accidents in our city caused by careless driving, particularly by teenagers who ride two-wheelers without helmets or licences.\n\nOver-speeding, stunt riding and use of mobile phones while driving endanger not only the riders but also pedestrians. Many families have lost young members, and parents live in constant fear. Last month, a student of our locality was seriously injured when a speeding motorcycle hit him near the market, and such incidents are now common.\n\nI urge the traffic police to check licences strictly and to fine violators. Schools should conduct road-safety workshops, and parents must not hand vehicles to underage children. Speed breakers should also be built near schools.\n\nI hope these steps will make our roads safer.\n\nYours faithfully\nDev Malhotra", marks: 5 },
      { q: "You are Neha Joshi, 31, Shivaji Nagar, Pune. Write a letter to the Editor of The Pune Herald about the shortage of drinking water in your locality during summer and suggest remedies. (120–150 words)", a: "31, Shivaji Nagar\nPune\n20 May 20XX\n\nThe Editor\nThe Pune Herald\nPune\n\nSubject: Acute shortage of drinking water in Shivaji Nagar\n\nSir\n\nThrough your newspaper, I wish to bring to the notice of the civic authorities the severe shortage of drinking water in Shivaji Nagar. For the past three weeks, taps have run dry for most of the day.\n\nResidents are forced to depend on expensive private tankers, and households with children and elderly people suffer the most. Leaking pipelines waste a large amount of water every day, while the demand rises in summer. Women who walk long distances to collect water lose valuable working hours, and small shopkeepers have also been forced to close early.\n\nI request the corporation to repair the leaking pipes immediately, ensure fair distribution by fixed timings and supply free tankers to needy families. Residents, too, should conserve water and adopt rainwater harvesting.\n\nI thank you for publishing my letter.\n\nYours faithfully\nNeha Joshi", marks: 5 },
      { q: "You are Karan Bedi, 7, Civil Lines, Jaipur. Write a letter to the Editor of The Rajasthan Post, Jaipur, about children spending too many hours on mobile games and the harm it causes. Suggest what parents and schools can do. (120–150 words)", a: "7, Civil Lines\nJaipur\n2 August 20XX\n\nThe Editor\nThe Rajasthan Post\nJaipur\n\nSubject: Excessive use of mobile games by children\n\nSir\n\nI would like to draw the attention of parents and teachers, through your columns, to the growing habit of children spending several hours daily on mobile games.\n\nThis habit harms eyesight, disturbs sleep and reduces time for study and outdoor play. Many children become irritable and withdraw from family and friends. Their marks also suffer. In several homes, children sit with phones even during meals, and family conversation has almost disappeared.\n\nParents should fix a daily screen limit and set an example by reducing their own phone use. Schools can promote sports, hobby clubs and reading hours. Games with age-appropriate content can be allowed for a short time only after homework is done.\n\nI am sure that a joint effort will help children grow healthy.\n\nYours faithfully\nKaran Bedi", marks: 5 },
      { q: "You are Ananya Reddy, 18, Banjara Hills, Hyderabad. Write a letter to the Editor of The Deccan Mail, Hyderabad, complaining about the heaps of plastic waste thrown in the lake near your colony and suggesting remedies. (120–150 words)", a: "18, Banjara Hills\nHyderabad\n9 June 20XX\n\nThe Editor\nThe Deccan Mail\nHyderabad\n\nSubject: Plastic waste in the lake near our colony\n\nSir\n\nI wish to draw the attention of the authorities, through your newspaper, to the heaps of plastic waste thrown into the lake near our colony. The water has become dirty, and a foul smell spreads in the evenings.\n\nFish are dying, and mosquitoes breed freely, causing diseases among residents. The lake, once a favourite spot for morning walkers, is now avoided by most people. Last week, I saw a cow fall ill after eating plastic bags near the bank, which shows how dangerous the situation has become.\n\nI request the municipal corporation to clean the lake immediately, install bins around its bank and impose fines on those who dump waste. Residents should avoid single-use plastic and join regular clean-up drives.\n\nI hope action will be taken without delay.\n\nYours faithfully\nAnanya Reddy", marks: 5 },
      { q: "You are Imran Qureshi, 22, Park Street, Kolkata. Write a letter to the Editor of The Eastern Observer, Kolkata, on the irregular running of city buses and the hardship it causes to office-goers and students. Suggest remedies. (120–150 words)", a: "22, Park Street\nKolkata\n14 July 20XX\n\nThe Editor\nThe Eastern Observer\nKolkata\n\nSubject: Irregular running of city buses\n\nSir\n\nThrough your esteemed newspaper, I wish to draw the attention of the transport authorities to the irregular and unreliable bus service on the Park Street route. Buses often arrive after long gaps and then come in a bunch.\n\nOffice-goers reach late, and students miss their classes and examinations. Overcrowded buses are also unsafe, particularly for women and the elderly. Many commuters are forced to hire costly taxis. Last Monday, I waited for forty minutes at the stop, and the three buses that finally arrived were so full that none could be boarded.\n\nI request the authorities to run buses at fixed intervals, to add more buses during peak hours and to display timetables at bus stops. A helpline for complaints would also help.\n\nI hope the matter will receive prompt attention.\n\nYours faithfully\nImran Qureshi", marks: 5 }
    ]
  },
  "job-application": {
    mcq: [
      { q: "A job application letter is usually written in reply to:", options: ["a newspaper report", "an advertisement for a vacancy", "a wedding invitation", "a bill"], answer: 1, explain: "It is a formal letter written in response to a **job advertisement**.", level: 1 },
      { q: "‘Encl.: Bio-data’ at the bottom of the letter means:", options: ["the letter is cancelled", "the writer's address is enclosed", "the bio-data is sent along with the letter", "the writer wants the bio-data returned"], answer: 2, explain: "**Encl.** stands for enclosure: a document sent along with the letter.", level: 1 },
      { q: "Which subject line is correct for a job application?", options: ["Application for the post of Accountant", "I want a job", "Accountant", "Please give me work"], answer: 0, explain: "The subject line reads ‘Application for the post of…’.", level: 1 },
      { q: "Which complimentary close is used in a job application?", options: ["Yours lovingly", "Yours sincerely", "Yours faithfully", "Your obedient son"], answer: 2, explain: "The receiver is addressed as Sir/Madam, so the close is **Yours faithfully**.", level: 1 },
      { q: "What belongs in the second paragraph of a job application?", options: ["A complaint about earlier employers", "Qualifications, experience and skills matched to the requirements", "A demand for a high salary", "A request for a holiday"], answer: 1, explain: "Paragraph 2 gives **qualifications, experience and skills** that suit the advertisement.", level: 2 },
      { q: "Which is the best way to refer to the advertisement?", options: ["I saw your ad somewhere and I want the job.", "Your vacancy is good, so I am applying.", "I am applying for the job you have.", "With reference to your advertisement in The Tribune dated 4 March 20XX, I wish to apply for the post of Sales Executive."], answer: 3, explain: "Name the source, the date and the post.", level: 2 },
      { q: "Which statement about the letter and the bio-data is true?", options: ["The letter is brief, and the bio-data gives the details in an organised way", "The bio-data is brief, and the letter lists all details", "Both contain exactly the same information", "The bio-data is written inside the letter body"], answer: 0, explain: "The letter persuades the employer in about 120–150 words, while the **bio-data** lists education, experience and personal details.", level: 2 },
      { q: "The advertisement asks for a fresh graduate. Which line would be wrong in an application by a fresh B.Com graduate?", options: ["I have recently completed my B.Com with 78 per cent.", "I have no work experience yet but am eager to learn.", "I did a short internship in a local firm.", "I have ten years of experience in handling company accounts."], answer: 3, explain: "A candidate must not invent experience. Use only the details given in the question.", level: 2 },
      { q: "A candidate writes: ‘Dear Sir, I want job. I am very hardworking, please give me anything at all. Yours sincerely.’ Which is the best assessment?", options: ["Correct, as it is short and honest", "Only the closing needs change", "Only the language needs improving", "It lacks address, date, receiver, subject, reference to the advertisement, qualifications and the correct close"], answer: 3, explain: "The letter lacks format and content and uses a wrong salutation and close. A job application must show how the writer **suits the post**.", level: 3 },
      { q: "An advertisement asks applicants to reply to ‘Box No. 22, The Hindustan Courier, Kanpur’. The applicant lives at 14, Civil Lines, Agra. Which receiver block is correct?", options: ["14, Civil Lines, Agra", "Box No. 22\nThe Hindustan Courier\nKanpur", "The Editor, Agra", "The applicant's own signature"], answer: 1, explain: "Write the address given in the advertisement as the receiver. The applicant's own address goes at the top.", level: 3 }
    ],
    written: [
      { q: "The following advertisement appeared in The Tribune dated 3 June: WANTED a Sales Executive for Shree Appliances, 45, Mall Road, Amritsar. Graduate with good communication skills. Apply with bio-data to the Manager, HR. You are Gurpreet Singh, 17, Model Town, Ludhiana, a B.Com graduate with a one-year internship in retail sales. Write an application. (120–150 words)", a: "17, Model Town\nLudhiana\n8 June 20XX\n\nThe Manager (HR)\nShree Appliances\n45, Mall Road\nAmritsar\n\nSubject: Application for the post of Sales Executive\n\nSir\n\nWith reference to your advertisement in The Tribune dated 3 June 20XX, I wish to apply for the post of Sales Executive in your organisation.\n\nI am a B.Com graduate and completed a one-year internship in retail sales, where I handled customers, explained product features and maintained sales records. I speak Punjabi, Hindi and English fluently, which helps me communicate well with customers. I am hardworking, punctual and a quick learner. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data is enclosed for your kind consideration. I shall be grateful if you call me for an interview, and I assure you of my sincere service if selected. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nGurpreet Singh\n\nEncl.: Bio-data", marks: 5 },
      { q: "Read the advertisement in The Hindu dated 10 July: REQUIRED a Junior Accountant for Kaveri Textiles, 12, Gandhi Road, Salem. B.Com with Tally knowledge. Apply to the General Manager. You are Lakshmi Narayanan, 8, Anna Nagar, Madurai, with a B.Com degree and a Tally certificate. Write an application. (120–150 words)", a: "8, Anna Nagar\nMadurai\n14 July 20XX\n\nThe General Manager\nKaveri Textiles\n12, Gandhi Road\nSalem\n\nSubject: Application for the post of Junior Accountant\n\nSir\n\nI have learnt from your advertisement in The Hindu dated 10 July 20XX that you require a Junior Accountant. I wish to offer myself as a candidate for the post.\n\nI hold a B.Com degree and a certificate course in Tally accounting software. I am accurate with figures, can prepare ledgers and balance sheets, and am familiar with basic taxation records. I am honest, careful and willing to work extra hours when required. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data is enclosed. I shall be thankful if you give me an opportunity to meet you for an interview. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nLakshmi Narayanan\n\nEncl.: Bio-data", marks: 5 },
      { q: "An advertisement in The Times of India dated 5 September invites applications for a Computer Teacher at Don Bosco Public School, Shillong. Qualifications: B.Tech or MCA with teaching interest. You are Rohit Das, 27, Laitumkhrah, Shillong, with an MCA degree and six months of tuition experience. Write an application. (120–150 words)", a: "27, Laitumkhrah\nShillong\n9 September 20XX\n\nThe Principal\nDon Bosco Public School\nShillong\n\nSubject: Application for the post of Computer Teacher\n\nSir\n\nI refer to your advertisement in The Times of India dated 5 September 20XX and wish to apply for the post of Computer Teacher in your school.\n\nI hold an MCA degree and have taught programming and basic computer skills to school students for six months in a tuition centre. I am familiar with Python and office software, and I enjoy simplifying difficult topics for children. I am patient, disciplined and keen to grow as a teacher. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data is enclosed. I request you to give me an opportunity to appear for an interview. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nRohit Das\n\nEncl.: Bio-data", marks: 5 },
      { q: "A Pune firm, Digital Dreams, advertised in Maharashtra Times dated 2 November for a Graphic Designer. Required: a diploma in design and a good portfolio. Reply to Box No. 31. You are Aditi Kulkarni, 6, Kothrud, Pune, with a diploma in graphic design and a portfolio of 40 designs. Write an application. (120–150 words)", a: "6, Kothrud\nPune\n6 November 20XX\n\nThe Manager (HR)\nDigital Dreams\nBox No. 31\nMaharashtra Times\nPune\n\nSubject: Application for the post of Graphic Designer\n\nSir\n\nWith reference to your advertisement in Maharashtra Times dated 2 November 20XX, I wish to apply for the post of Graphic Designer.\n\nI hold a diploma in graphic design and have created a portfolio of forty designs, including posters, logos and social media graphics. I am skilled in design software and work well within deadlines. My creative ideas and attention to detail would, I believe, be an asset to your company. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data and a link to my portfolio are enclosed. I shall be happy to appear for an interview at your convenience. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nAditi Kulkarni\n\nEncl.: Bio-data", marks: 5 },
      { q: "Read the advertisement in Dainik Jagran dated 15 February: WANTED a Receptionist for Hotel Ganga View, Haridwar. Graduate with fluency in Hindi and English, pleasant personality. Apply to the Manager. You are Pooja Rawat, 3, Rajpur Road, Dehradun, a graduate who has worked as a front-desk assistant for one year. Write an application. (120–150 words)", a: "3, Rajpur Road\nDehradun\n18 February 20XX\n\nThe Manager\nHotel Ganga View\nHaridwar\n\nSubject: Application for the post of Receptionist\n\nSir\n\nI have read your advertisement in Dainik Jagran dated 15 February 20XX for the post of Receptionist and wish to offer my services.\n\nI am a graduate and have worked for one year as a front-desk assistant, where I welcomed guests, handled bookings and answered telephone calls. I am fluent in Hindi and English and have a pleasant manner. I can work in shifts and handle difficult situations calmly. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data is enclosed. I would be grateful if you called me for an interview, and I assure you of my honest work. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nPooja Rawat\n\nEncl.: Bio-data", marks: 5 },
      { q: "A school in Patna advertised in The Telegraph dated 12 April for a Librarian. Required: a degree in Library Science and one year of experience. Apply to the Principal, Gyan Jyoti School, Patna. You are Sunil Prasad, 11, Boring Road, Patna, with a B.Lib.Sc degree and one year of experience in a college library. Write an application. (120–150 words)", a: "11, Boring Road\nPatna\n16 April 20XX\n\nThe Principal\nGyan Jyoti School\nPatna\n\nSubject: Application for the post of Librarian\n\nSir\n\nWith reference to your advertisement in The Telegraph dated 12 April 20XX, I wish to apply for the post of Librarian in your school.\n\nI hold a Bachelor's degree in Library Science and have one year of experience in a college library, where I catalogued books, issued them and kept records. I can use library software and am keen to encourage reading among students through book clubs and displays. I am orderly, patient and dependable. I believe my education and training have prepared me well for the duties of this post.\n\nMy bio-data is enclosed for your kind perusal. I request you to give me an opportunity to appear for an interview. I am ready to join at short notice and to work with full dedication. I shall remain obliged to you.\n\nYours faithfully\nSunil Prasad\n\nEncl.: Bio-data", marks: 5 }
    ]
  },
  "article-writing": {
    mcq: [
      { q: "The line giving the writer's name below the title of an article is called:", options: ["a salutation", "a byline", "a subject line", "a caption"], answer: 1, explain: "The **byline** reads ‘By’ followed by the writer's name.", level: 1 },
      { q: "What is the usual word limit for an article in the Class 12 paper?", options: ["About 50 words", "About 80 words", "About 120–150 words", "About 300 words"], answer: 2, explain: "The article is of about **120–150 words**.", level: 1 },
      { q: "A good title for an article should be:", options: ["a full paragraph", "short, catchy and relevant", "the writer's address", "the date of writing"], answer: 1, explain: "A title should be short and attract the reader.", level: 1 },
      { q: "Which of these is NOT part of the format of an article?", options: ["Title", "Byline", "Conclusion", "Complimentary close such as ‘Yours faithfully’"], answer: 3, explain: "An article is not a letter. It has a title, byline, introduction, body and conclusion.", level: 1 },
      { q: "Which sentence makes the best hook for an article on digital addiction?", options: ["Digital addiction is a topic.", "I am going to write on digital addiction.", "What would you do if your phone could not be charged for a week?", "Many things are happening today."], answer: 2, explain: "An opening question or striking situation draws the reader in.", level: 2 },
      { q: "Which linking word best shows contrast in ‘Technology helps us; ___, its misuse harms us’?", options: ["moreover", "however", "therefore", "similarly"], answer: 1, explain: "‘However’ shows contrast. ‘Moreover’ adds, ‘therefore’ shows result, ‘similarly’ compares.", level: 2 },
      { q: "Which is the most suitable conclusion for an article on water conservation?", options: ["Let us all conserve every drop today, for tomorrow's generations depend on it.", "Cricket is a popular game in India.", "I have written enough on this topic.", "The reader may do what he likes."], answer: 0, explain: "A conclusion sums up and ends with a **thought or call to action** related to the topic.", level: 2 },
      { q: "When supporting an article with statistics, a student should:", options: ["invent impressive numbers", "use only facts he or she is sure of", "avoid using any examples", "copy a paragraph from a textbook"], answer: 1, explain: "Never invent figures. Use only facts you know to be correct, or general examples.", level: 2 },
      { q: "Rhea's article is 190 words long. It has an introduction of 20 words, a body of 150 words and no conclusion. What is the best advice?", options: ["Add a second conclusion", "Shorten the body, add a short conclusion and keep within 120–150 words", "Delete the introduction", "Leave it unchanged"], answer: 1, explain: "The article exceeds the limit and lacks a conclusion. Structure and word limit both matter.", level: 3 },
      { q: "Ravi plans an article on ‘Digital detox’: title, hook, causes and effects, solutions, closing thought. Which element of the format is missing from his plan?", options: ["The byline", "A salutation", "A sender's address", "A subject line"], answer: 0, explain: "The title and the byline (‘By Ravi Menon’) are both required. The other items belong to letters.", level: 3 }
    ],
    written: [
      { q: "Write an article on ‘The Importance of Reading Habit among Teenagers’ in 120–150 words. You are Tanvi Mehra. (120–150 words)", a: "THE JOY OF READING\nBy Tanvi Mehra\n\nHow many of us can remember the last book we finished? In an age of screens, reading has become a forgotten pleasure among teenagers. Libraries and e-books have also made good books easily available.\n\nReading widens our knowledge and improves vocabulary and writing skills. It sharpens concentration, which is often lost in endless scrolling. Stories also build empathy by helping us see the world through others' eyes. Students who read regularly generally express themselves better in examinations and interviews.\n\nParents and schools can help by setting aside a daily reading hour, stocking libraries with interesting books and starting book clubs. Teenagers, too, should begin with subjects they love, such as sports, science fiction or biographies.\n\nA good book is a lifelong friend. Let us pick one up today and rediscover the pleasure of reading.", marks: 5 },
      { q: "Write an article on ‘Road Safety: Everyone's Responsibility’ for your school magazine. You are Arjun Nair. (120–150 words)", a: "ROAD SAFETY: A SHARED DUTY\nBy Arjun Nair\n\nEvery day, newspapers carry reports of road accidents. Most of them could have been avoided if drivers and pedestrians had followed a few simple rules. Helmets and seat belts alone can save many lives.\n\nSpeeding, drunk driving, not wearing helmets and seat belts, and using mobile phones while driving are the main causes. Poor roads and broken signals add to the danger. The result is loss of life, injuries and grief for families.\n\nTraffic police should enforce rules strictly, but citizens must also cooperate. Drivers should obey signals and speed limits, pedestrians should use zebra crossings, and schools should teach road sense from an early age.\n\nSafety on the road is not the work of the police alone. If each of us takes care, our roads will become safer for all.", marks: 5 },
      { q: "Write an article on ‘Digital Detox: Why Teenagers Need a Break from Screens’. You are Simran Kaur. (120–150 words)", a: "SWITCH OFF TO SWITCH ON\nBy Simran Kaur\n\nWhat would you do if your phone could not be charged for a week? For many teenagers, the very thought brings anxiety. Parents can also guide children gently, and not forcefully, towards healthier habits.\n\nConstant use of phones and social media harms health. It strains the eyes, causes sleeplessness, reduces attention and makes young people compare themselves unfairly with others. Real friendships and family conversations suffer, and studies are neglected.\n\nA digital detox means setting aside fixed hours without screens. Meals, bedtime and family time should be phone-free. Teenagers can replace screen time with sports, music, reading or a walk with friends. Apps that limit usage can also help.\n\nTechnology is a good servant but a bad master. A short break from screens may bring us closer to ourselves and to those we love.", marks: 5 },
      { q: "Write an article on ‘Plastic Pollution: A Threat We Can Control’. You are Vivek Rao. (120–150 words)", a: "SAY NO TO PLASTIC\nBy Vivek Rao\n\nWalk along any river bank or street, and the sight of discarded plastic bags and bottles is unavoidable. Plastic, once a convenience, has become a serious threat. Even small steps, such as refusing a plastic straw, add up when millions follow them.\n\nPlastic does not decompose for a very long time. It chokes drains, causes floods, poisons soil and harms cattle and sea animals that swallow it. Burning it releases harmful fumes.\n\nThe solution lies in our hands. We can carry cloth bags, use steel bottles, refuse single-use plastic and recycle whatever we can. Governments should enforce bans strictly and promote eco-friendly alternatives. Schools can run awareness drives and clean-up campaigns.\n\nIf each one of us changes small habits, we can protect our planet for future generations. The time to act is now.", marks: 5 },
      { q: "Write an article on ‘Stress among Students during Board Examinations’ for the school magazine. You are Nandini Pillai. (120–150 words)", a: "BEATING EXAM STRESS\nBy Nandini Pillai\n\nAs board examinations draw near, many students feel butterflies in their stomachs. A little tension is natural, but too much of it can harm performance and health. A cheerful chat with friends and family, or a walk in the open air, can also lighten the burden.\n\nThe pressure of marks, comparison with classmates and expectations from parents often cause sleeplessness, headaches and loss of appetite. Poor planning and last-minute study make matters worse.\n\nStudents can manage stress by making a realistic timetable, revising regularly and taking short breaks. Proper sleep, a balanced diet and daily exercise or meditation keep the mind calm. Parents should offer support and not pressure, while teachers can guide and encourage.\n\nExaminations test our preparation, not our worth. If we stay calm and confident, success will follow.", marks: 5 },
      { q: "Write an article on ‘The Need to Save Water’ in 120–150 words. You are Harsh Vardhan. (120–150 words)", a: "EVERY DROP COUNTS\nBy Harsh Vardhan\n\nWater is life, yet many of us waste it as if it will never end. Several parts of our country already face acute shortages, especially in summer. Fixing broken pipes in homes and offices can also save a great deal of water.\n\nRapid population growth, overuse of groundwater, pollution of rivers and careless habits like leaving taps running are the major causes. As a result, wells dry up, farmers suffer and families walk long distances to fetch water.\n\nWe can save water by repairing leaking taps, reusing water for plants and avoiding wastage while brushing or bathing. Rainwater harvesting should be made compulsory in buildings, and industries must be stopped from polluting rivers.\n\nLet us remember that the water we save today is the water our children will drink tomorrow.", marks: 5 }
    ]
  },
  "report-writing": {
    mcq: [
      { q: "A newspaper report of an event that has already taken place is written in the:", options: ["present tense", "future tense", "past tense", "imperative mood"], answer: 2, explain: "A report records past events, so it uses the **past tense**.", level: 1 },
      { q: "Which voice is commonly used in a report?", options: ["Passive voice", "Active voice only, always with ‘I’", "Imperative voice", "Subjunctive voice"], answer: 0, explain: "The passive voice keeps the focus on the event, e.g. ‘The fair was inaugurated by…’.", level: 1 },
      { q: "Which items are written in a report?", options: ["Address, date, salutation, body and close", "Only a box and a date", "Heading, byline and body", "Subject line and enclosure"], answer: 2, explain: "A report has a **heading, a byline and a body**, and no address, salutation or close.", level: 1 },
      { q: "A report should be:", options: ["full of personal feelings", "factual and objective", "written in the first person", "a conversation"], answer: 1, explain: "A report states facts. The writer stays in the background.", level: 1 },
      { q: "Which is the best heading for a report on a science fair?", options: ["Science fair is great fun!", "Inter-School Science Fair Held in Pune", "I attended a science fair", "Science fair will be held in Pune"], answer: 1, explain: "A heading is short and factual and, for a past event, is in the past tense.", level: 2 },
      { q: "Which is the correct way to report what the chief guest said?", options: ["The chief guest said, ‘I am happy to be here.’", "The chief guest says that I am happy to be here.", "The chief guest said that she was happy to be there.", "The chief guest was saying I am happy."], answer: 2, explain: "Reports use **reported speech**, with the tense and pronoun changed.", level: 2 },
      { q: "Which sentence is unsuitable in a report?", options: ["The function began at 10 a.m.", "Prizes were distributed to the winners.", "I was thrilled to see the dances.", "The chief guest was welcomed by the Principal."], answer: 2, explain: "A report avoids ‘I’ and personal feelings.", level: 2 },
      { q: "In a three-paragraph report, which order is best?", options: ["Prizes, welcome, introduction", "Details of programme, event introduction, conclusion", "Event introduction, details of programme, conclusion with results", "Conclusion, introduction, details"], answer: 2, explain: "Open with what, where, when and who. Then describe the programme and end with results or reactions.", level: 2 },
      { q: "The chief guest said, ‘I will support this school.’ Which is the correct reported form?", options: ["The chief guest said that she would support that school.", "The chief guest said that I will support this school.", "The chief guest said that she would have supported that school.", "The chief guest said that she supports that school."], answer: 0, explain: "In reported speech, ‘I’ becomes ‘she’, ‘will’ becomes ‘would’ and ‘this’ becomes ‘that’.", level: 3 },
      { q: "A student's report on a sports day says: ‘I think the day was wonderful. We will give prizes at 4 p.m. Everyone enjoys the races.’ Which describes the faults?", options: ["Only the heading is missing", "It uses first person, opinion and present/future tenses instead of third person, facts and past tense", "Only the date is missing", "No fault, since it is lively"], answer: 1, explain: "A report is factual and in the past tense, with the passive voice and third person, and no opinions.", level: 3 }
    ],
    written: [
      { q: "You are Rahul Sinha, a reporter of The Capital Times, Bhopal. Write a report of the Annual Day celebrations held on 16 December at Navodaya Public School, Bhopal. The chief guest was Dr Sarita Menon, a scientist, and cultural items were presented. Prizes were given. (120–150 words)", a: "ANNUAL DAY CELEBRATED AT NAVODAYA PUBLIC SCHOOL\nBy Rahul Sinha\n\nBhopal, 17 December: Navodaya Public School celebrated its Annual Day on 16 December at the school auditorium. Dr Sarita Menon, a scientist, was the chief guest.\n\nThe function began with a prayer, followed by the Principal's welcome address and the annual report. Students presented a classical dance, a skit on environment protection and a medley of folk songs, which were loudly applauded by parents. Dr Menon, in her address, said that curiosity and hard work were the keys to success. The audience was particularly impressed by the colourful costumes and the confident performances of the students.\n\nMedals and certificates were awarded to the toppers and to winners of sports and cultural events. The programme ended with a vote of thanks by the Head Boy and the national anthem.", marks: 5 },
      { q: "You are Preeti Joshi, a reporter of The Hill Courier, Shimla. Write a report on the inter-school football tournament held on 8 November at Ridge Ground, Shimla, in which Pine Grove School beat Mount View School 3–1 in the final. (120–150 words)", a: "PINE GROVE SCHOOL WINS INTER-SCHOOL FOOTBALL TOURNAMENT\nBy Preeti Joshi\n\nShimla, 9 November: Pine Grove School won the Inter-School Football Tournament by defeating Mount View School 3–1 in the final played at Ridge Ground on 8 November.\n\nEight teams had participated in the three-day tournament, which was inaugurated by the Sports Officer of the district. The final match was keenly contested. Mount View took an early lead, but Pine Grove equalised before half-time and scored two more goals in the second half. A large crowd of students and teachers cheered both teams. The match was watched with great excitement, as both teams played with great skill, speed and sportsmanship.\n\nThe trophy was presented to the winning captain by the chief guest, and the Player of the Tournament was also awarded. The Principal of Pine Grove School thanked the organisers.", marks: 5 },
      { q: "You are Mohit Verma, a reporter of The Gomti Gazette, Lucknow. Write a report on a seminar on ‘Cyber Safety’ organised at Lotus Valley School, Lucknow on 21 September for students of Classes XI and XII. The speaker was Mr Imran Khan, a cyber expert. (120–150 words)", a: "SEMINAR ON CYBER SAFETY HELD AT LOTUS VALLEY SCHOOL\nBy Mohit Verma\n\nLucknow, 22 September: A seminar on ‘Cyber Safety’ was organised at Lotus Valley School on 21 September for students of Classes XI and XII. Mr Imran Khan, a cyber expert, was the speaker.\n\nHe explained common online dangers such as phishing, identity theft and cyber bullying through real-life examples. Students were advised to use strong passwords, avoid sharing personal details and report suspicious activity to elders. He also said that they should think before posting anything online, since the internet never forgets. Many students noted down the tips given by the speaker for use at home.\n\nThe session ended with a lively question-and-answer round, in which students asked about safe online behaviour. The Principal thanked the speaker and said that such sessions would be held every term.", marks: 5 },
      { q: "You are Pallavi Nair, a reporter of The Kochi Chronicle. Write a report on a tree plantation drive held on 5 June (World Environment Day) at Seaview Higher Secondary School, Kochi, in which 200 saplings were planted. (120–150 words)", a: "200 SAPLINGS PLANTED AT SEAVIEW SCHOOL\nBy Pallavi Nair\n\nKochi, 6 June: Seaview Higher Secondary School organised a tree plantation drive on 5 June to mark World Environment Day. About 200 saplings were planted on the school campus and along the neighbouring road.\n\nThe drive was inaugurated by the Principal, who planted the first sapling. Members of the Eco Club, supported by NCC cadets and teachers, took part in the programme. Neem, mango, gulmohar and jamun trees were planted, and each class adopted a group of saplings. Teachers helped the younger students to dig pits, place saplings and water them carefully.\n\nIn his address, a forest officer, the chief guest, urged students to care for the plants and to save the environment. The drive ended with an oath to protect trees, taken by all the participants.", marks: 5 },
      { q: "You are Anil Gupta, a reporter of The Ganga Times, Varanasi. Write a report on a book fair held from 10 to 14 January at Sarvodaya School, Varanasi, inaugurated by the poet Dr Kamla Mishra. (120–150 words)", a: "BOOK FAIR AT SARVODAYA SCHOOL ATTRACTS HUNDREDS\nBy Anil Gupta\n\nVaranasi, 15 January: A five-day book fair was held at Sarvodaya School from 10 to 14 January. It was inaugurated by the poet Dr Kamla Mishra.\n\nMore than twenty publishers set up stalls with books on literature, science, history and children's stories. Students, parents and teachers visited the fair in large numbers, and special discounts were offered on school-library purchases. Competitions in storytelling and poetry recitation were also held. Visitors were seen carrying away bags full of books and spoke highly of the choice available.\n\nIn her address, Dr Mishra said that books were the best companions and urged students to read regularly. On the last day, prizes were given to the winners of the competitions. The Principal thanked the publishers and the students who had helped in organising the fair.", marks: 5 },
      { q: "You are Zoya Siddiqui, a reporter of The Deccan Daily, Hyderabad. Write a report on a free medical camp organised by the Rotary Club on 12 March at Charminar Community Hall, Hyderabad. About 300 people were examined. (120–150 words)", a: "FREE MEDICAL CAMP HELD AT CHARMINAR COMMUNITY HALL\nBy Zoya Siddiqui\n\nHyderabad, 13 March: The Rotary Club organised a free medical camp on 12 March at the Charminar Community Hall. About 300 people from nearby localities were examined.\n\nA team of doctors conducted general check-ups, eye tests and dental examinations. Blood pressure and sugar levels were also checked, and free medicines were distributed to patients. Volunteers from local colleges helped to register patients and guided elderly visitors. Patients with serious complaints were advised to consult the nearby government hospital.\n\nThe camp was inaugurated by the Deputy Mayor, who praised the club for its service to society. The doctors advised the visitors to exercise daily and eat a balanced diet. The President of the club thanked the doctors and volunteers and announced that a similar camp would be organised next year.", marks: 5 }
    ]
  }
});
